import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易集註 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易集註 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"classics/jizhu/037.md","filePath":"classics/jizhu/037.md"}'),l={name:"classics/jizhu/037.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>遁者，退避也，六月之卦也。不言退而曰遁者，退止有退後之義，無避禍之義，所以不言退也。為卦天下有山，山雖高，其性本止。天之陽，性上進，違避而去，故有遁去之義。且二陰生於下，陰漸長，小人漸盛，君子退而避之，故為遁也。《序卦》“恆者久也，物不可以久居其所”，久則變，變則去，此理之常，所以次恆。</p><p>亨為君子言也。君子能遁，則身雖遁而道亨。小者，陰柔之小人也。指下二陰也。利貞者，小者利於正，而不害君子也。若害君子，小人亦不利也。</p><p>《彖》曰：遁亨，遁而亨也。剛當位而應，與時行也。小利貞，浸而長也。遁之時義大矣哉!浸居鴆反</p><p>以九五一爻釋亨，以下二陰爻釋利貞而贊之。遁而亨者，惟遁乃亨，見其不可不遁也。剛指五，當位者，當中正之位。而應者，下與六二相應也。時行，言順時而行。身雖在位，而心則遁，此所以謂之時行也。九五，有中正之德，六二能承順之，似亦可以不必於遁。然二陰浸而長，時不可不遁，知時之當遁，與時偕行，此其所以亨也。浸者漸也，浸而長，其勢必至於害君子，故戒以利貞。時義大者，陰雖浸長，尚未盛大，且九五與二相應，其陽漸消之意，皆人之所未見而忽略者。是以茍且流連，而不能決去也。當此之時，使不審時度勢，則不知遁。若眷戀祿位，又不能遁。惟有明哲保身之智，又有介石見幾之勇，方能鴻冥鳳舉，所以嘆其時義之大。漢元成之時，弘恭石顯得志於內，而蕭望之劉向朱雲皆得巨禍。桓靈之際，曹節王甫得志於內，而李膺陳蕃竇武皆被誅戮，均不知遁之時義者也。易中大矣哉有二，有讚美其所繫之大者，豫革之類是也;有稱歎其所處之難者，大過遁之類是也。</p><h3 id="《象》曰-天下有山-遁-君子以遠小人-不惡而嚴。遠袁萬反" tabindex="-1">《象》曰：天下有山，遁，君子以遠小人，不惡而嚴。遠袁萬反 <a class="header-anchor" href="#《象》曰-天下有山-遁-君子以遠小人-不惡而嚴。遠袁萬反" aria-label="Permalink to “《象》曰：天下有山，遁，君子以遠小人，不惡而嚴。遠袁萬反”">​</a></h3><p>惡者，惡聲厲色，疾之已甚也。嚴者，以禮律身，無可議之隙，而凜然不可犯也。不惡者待彼之禮，嚴者守己之節。天下有山，天雖無意於絕山，而山自不能以及乎天，遁之象也。故君子以遠小人，不惡而嚴。曰不惡而嚴則君子無心於遠小人，而小人自遠，與天之無心於遠山，而山自絕於天者同矣。遠小人，艮止象。不惡而嚴，乾剛象。</p><p>初六，遁尾厲，勿用有攸往。</p><p>遁者，居當遁之時也。尾者初也，因在下，故曰尾。厲者天下賢人君子皆以遁去，時何時也?豈不危厲。往者，往而遁去也。本卦遁，乃陽剛與陰，不相干涉，故不可往，且初在下，無位，又陰柔，所居不正，無德無位。無德則無聲聞，不過凡民耳。與遁去之賢人君子不同，遁之何益?</p><p>初六居下當遁之時，亦危厲矣。但時雖危厲，而當遁者非初之人，故教佔者勿用遁去，但晦處以俟時可也。</p><h3 id="《象》曰-遁尾之厲-不往何災也" tabindex="-1">《象》曰：遁尾之厲，不往何災也? <a class="header-anchor" href="#《象》曰-遁尾之厲-不往何災也" aria-label="Permalink to “《象》曰：遁尾之厲，不往何災也?”">​</a></h3><p>不遁有何災咎，所以勿用有攸往。</p><p>六二，執之用黃牛之革，莫之勝說。勝音升，說音脫</p><p>執者執縛也。艮性止，執之象也。黃中色，指二。應爻錯坤，牛之象也。勝者任也，脫者解脫也。能勝其脫，欲脫即脫矣。莫之勝脫者，不能脫也。言執縛之以黃牛之皮，與九五相交之志堅固不可脫也。本卦遁者乃陽，初與二陰爻皆未遁，故此爻不言遁字。</p><p>二陰浸長，近於上體之四陽*，已凌迫於陽矣。然二與五為正應，二以中正順應乎五，五以中正親合乎二，正所謂剛當位而應，不凌迫乎陽，可知矣。故有執之用黃牛之革，莫之勝說之象。佔者是時亦當如此也。</p><ul><li>原文作“陰”，為“陽”之誤。</li></ul><h3 id="《象》曰-執用黃牛-固志也。" tabindex="-1">《象》曰：執用黃牛，固志也。 <a class="header-anchor" href="#《象》曰-執用黃牛-固志也。" aria-label="Permalink to “《象》曰：執用黃牛，固志也。”">​</a></h3><p>堅固其二五中正相合之志也。</p><p>九三，系遁，有疾厲，畜臣妾吉。</p><p>系者，心維繫而眷戀也。高祖有疾，手敕惠帝曰：“吾得疾隨困，以如意母子相累，其餘諸兒皆足自立，哀此兒猶小也。”曹瞞臨死持姬女而指季豹以示四子曰：“以累汝。”因泣下。此皆所謂系也。中爻為巽，巽為繩，系之象也。系遁者，懷祿徇私，隱忍而不去也。疾者，利慾為纏魔，困苦之疾也。厲者禍伏於此而危厲也，臣者僕也，妾者女子也，指下二陰也，乃三所繫戀之類也。蓋臣妾也，宮室也，利祿也，凡不出於天理之公，而出於人慾之私者，皆陰之類也，皆人之所繫戀者也。本卦止言臣妾者，因二陰居下位故也。畜者止也，與剝卦順而止之同，止之使制於陽而不陵上也。艮畜止象，又為閽寺，臣之象，又錯兌，妾之象。</p><p>九三當陰長凌陽之界，與初二二爻同體，下比於陰，故有當遁而繫戀之象。既有所繫，則不能遁矣，蓋疾而為厲之道也。然艮性能止，惟剛正自守，畜止同體，在下二陰馭之以臣妾之正道，使制於陽，而不陵上，斯吉矣，故又教佔者必如此。</p><h3 id="《象》曰-系遁之厲-有疾憊也-畜臣妾吉-不可大事也。" tabindex="-1">《象》曰：系遁之厲，有疾憊也;畜臣妾吉，不可大事也。 <a class="header-anchor" href="#《象》曰-系遁之厲-有疾憊也-畜臣妾吉-不可大事也。" aria-label="Permalink to “《象》曰：系遁之厲，有疾憊也;畜臣妾吉，不可大事也。”">​</a></h3><p>疾憊者，疲憊於私慾，困而危矣。不可大事者，出處去就，乃大丈夫之大事。知此大事，方知其遁。若畜止臣妾，不過以在我艮止之性，禁令之爾，乃小事也。九三系遁，能此小事，亦即吉矣，豈能決斷其出處去就之大事哉。</p><p>九四，好遁，君子吉，小人否。好呼報反，否方有反</p><p>三比二，故曰系。四應初，故曰好。好者愛也，系者縛也，愛者必眷戀而縛，縛者因喜悅而愛，其實一也。好遁者，又好而又遁也。好者爵位利祿，愛慕之事也。遁者審時度勢，見幾之事也。好者四也，遁者九也。陽居陰位，陽可為君子，陰可為小人，故可好可遁也。所以聖人設小人之戒。否者不也。</p><p>九四以剛居柔，下應初六，故有好而不遁之象。然幹體剛健，又有遁而不好之象。佔者顧其人何如耳，若剛果之君子，則有以勝其人慾之私，止知其遁，不知其好，得以遂其潔身之美，故吉矣。若小人，則徇欲忘反，止知其好，不知其遁，遁豈所能哉，故在小人則否也。</p><h3 id="《象》曰-君子好遁-小人否也。" tabindex="-1">《象》曰：君子好遁，小人否也。 <a class="header-anchor" href="#《象》曰-君子好遁-小人否也。" aria-label="Permalink to “《象》曰：君子好遁，小人否也。”">​</a></h3><p>君子剛果，故好而知遁，必於其遁。小人陰柔，故好而不知遁，惟知其好矣。</p><p>九五，嘉遁，貞吉。</p><p>嘉遁者，嘉美乎六二也。當二陰浸長之時，二以艮體，執之以黃牛之革，不凌犯乎陽，其志可謂堅固矣。為君者，不嘉美以正其志，安能治遁，故貞吉。若人君，無逃遁之理。玄宗幸蜀，安得為嘉。</p><p>九五陽剛中正，有治遁之才者也。當天下賢人君子遁去之時，下應六二之中正，見六二之志固，乃褒嘉之，表正其志，以成其不害賢人君子之美，正而且吉之道也，故其象佔如此。</p><h3 id="《象》曰-嘉遁貞吉-以正志也。" tabindex="-1">《象》曰：嘉遁貞吉，以正志也。 <a class="header-anchor" href="#《象》曰-嘉遁貞吉-以正志也。" aria-label="Permalink to “《象》曰：嘉遁貞吉，以正志也。”">​</a></h3><p>二之固志者，堅固其事上之志，臣道中正之心也。五之正志者，表正其臣下之志，君道中正之心也。二五小象皆同言志字，所以知五褒嘉乎二。</p><p>上九，肥遁，無不利。</p><p>肥者，疾憊之反。遁字從豚，故初六言尾，上九言肥，皆象豚也。以陽剛之賢，而居霄漢之上。睟面盎背，莫非道德之豐腴。手舞足蹈，一皆仁義之膏澤。心廣體胖，何肥如之。無不利者，天子不得臣，諸侯不得友，堯雖則天，不屈飲犢之高。武既應人，終全孤竹之節。理亂不聞，寵辱不驚，何利如之。</p><p>諸爻皆疑二陰之浸長，心既有所疑而慼慼，則身亦隨之而疾瘠矣，安能肥乎?惟上九，以陽剛而居卦外，去柔最遠，無所繫應，獨無所疑，蓋此心超然於物外者也，故有肥遁之象，佔無不利可知矣。</p><h3 id="《象》曰-肥遁無不利-無所疑也。" tabindex="-1">《象》曰：肥遁無不利，無所疑也。 <a class="header-anchor" href="#《象》曰-肥遁無不利-無所疑也。" aria-label="Permalink to “《象》曰：肥遁無不利，無所疑也。”">​</a></h3><p>無所疑者，不疑二陰之浸長而消陽也。無所疑，所以逍遙物外，不至於愁苦而疾瘠。</p>',38)])])}const f=e(l,[["render",t]]);export{_ as __pageData,f as default};
